# Occupied hours: weekday, hours 8-17 local time (assume UTC labels)
def occ(t):
    dt = datetime.fromisoformat(t)
    return dt.weekday() < 5 and 8 <= dt.hour <= 17

def is_before(t):
    return datetime.fromisoformat(t) < datetime(2018,6,15)

def stats(key):
    before = []
    after = []
    for t,v in data[key].items():
        if occ(t):
            (before if is_before(t) else after).append(v)
    mb = sum(before)/len(before) if before else None
    ma = sum(after)/len(after) if after else None
    return mb, ma, len(before), len(after)

for k in series_ids:
    mb, ma, nb, na = stats(k)
    d = (ma-mb) if mb is not None and ma is not None else None
    print(f"{k}: before={mb:.3f}, after={ma:.3f}, diff={d:+.3f} (n={nb},{na})")

